  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 21, $j$6.1 Research and the Synthesis Essay$j$, $j${"readings": [{"title": "Romans 12 (King James Version)", "url": "/portal/bible/Romans/12"}], "body": "College writing often asks you to synthesize, to bring together ideas from several sources into a new, supported point of your own. A synthesis essay is not a summary of sources one after another. It uses sources as voices in a conversation, and your thesis is your own contribution.\n\nBegin with a question you want to answer. Search for credible sources: books, scholarly articles, government and university websites, and reputable news. Judge each source by authority (who wrote it and what is their expertise), accuracy (can the facts be checked), currency (how recent) and purpose (to inform, persuade or sell). Primary sources are original materials such as letters, speeches and data. Secondary sources interpret them.\n\nTake notes by paraphrasing in your own words, and put quotation marks around any words you copy. Plagiarism is presenting someone else's words or ideas as your own, and it is dishonest. Give credit with a consistent citation style such as MLA, using in text citations and a Works Cited list.\n\nTo build your essay, write a thesis, group sources by idea, and for each paragraph give a topic sentence, evidence from two or more sources, and your analysis explaining how the sources connect.\n\nHonesty in scholarship is a moral matter. Romans 12:17 says, Provide things honest in the sight of all men.\n\nYour task: (1) Define synthesis and explain how it differs from summary. (2) List the four tests for judging a source. (3) Write a research question and a one sentence thesis for a topic from this course.\n\nFlorida standards: ELA.12.C.1.4, ELA.12.C.4.1, ELA.K12.EE.1.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.12.C.1.4, ELA.12.C.4.1, ELA.K12.EE.1.1", "script": "Welcome to our final unit. Listen, everything you have learned in this course now comes together in the writing and speaking you will do in college, in work and in ministry.\n\nWe begin with research. College writing often asks you to synthesize. That means bringing together ideas from several sources into a new, supported point of your own. A synthesis essay is not a list of summaries. The sources are voices in a conversation, and your thesis is your own contribution.\n\nNow watch this. Start with a question. Then judge every source with four tests. Authority, who wrote it and what is their expertise. Accuracy, can the facts be checked. Currency, how recent is it. And purpose, is it to inform, persuade or sell.\n\nTake notes in your own words, and put quotation marks around any words you copy. Plagiarism is presenting someone else's words or ideas as your own, and it is dishonest. Give credit with a consistent citation style like MLA, with in text citations and a Works Cited list.\n\nRomans 12:17 says, Provide things honest in the sight of all men. Your task is to define synthesis, list the four tests, and write a research question and a thesis. Take the four question check. Be honest in your work. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.1 Research and the Synthesis Essay$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 22, $j$6.2 The Personal Narrative and the College Application Essay$j$, $j${"readings": [{"title": "Proverbs 27 (King James Version)", "url": "/portal/bible/Proverbs/27"}], "body": "A personal narrative tells a true story from your own life and shows what it taught you. Colleges often ask for one, and scholarship committees do too. They want to know who you are beyond your grades.\n\nChoose a specific moment, not a general theme. A strong essay begins with a small scene, perhaps a few lines of dialogue, a place, or an action, and then widens to its meaning. For example, an essay about leadership might begin at six in the morning, with a student unlocking a church kitchen to prepare breakfast for the neighborhood, and then show what that service taught him about humility.\n\nUse the narrative techniques you have studied: concrete details, dialogue, pacing, a clear point of view and a reflective close. Show, do not only tell. Instead of saying I am hardworking, describe the tasks that prove it.\n\nStructure matters. Open with a hook, build to a turning point, and close with reflection, saying what you learned and how you will carry it forward. Most application essays are about 500 to 650 words. Revise with care: ask a trusted adult to read your draft, cut repetition, and read it aloud.\n\nBe honest and humble. Proverbs 27:2 says, Let another man praise thee, and not thine own mouth. You can share accomplishments plainly, without boasting.\n\nYour task: (1) Name three features of a strong application essay. (2) Write an opening scene of 4 to 6 sentences for a personal narrative. (3) Explain how your scene leads to a lesson.\n\nFlorida standards: ELA.12.C.1.2, ELA.12.C.3.1, ELA.12.C.1.5.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.12.C.1.2, ELA.12.C.3.1, ELA.12.C.1.5", "script": "Now let's talk about telling your own story. Listen, a personal narrative tells a true story from your life and shows what it taught you. Colleges ask for one. Scholarship committees ask for one. They want to know who you are beyond your grades.\n\nChoose a specific moment, not a general theme. Begin with a small scene, a few lines of dialogue, a place or an action, and then widen to the meaning. Picture a student unlocking a church kitchen at six in the morning to prepare breakfast for the neighborhood. That is a scene, and it can lead to a lesson about humility.\n\nNow watch this. Use the narrative techniques you have studied: concrete details, dialogue, pacing, a clear point of view and a reflective close. Show, do not only tell. Instead of saying I am hardworking, describe the tasks that prove it.\n\nOpen with a hook. Build to a turning point. Close with reflection, what you learned and how you will carry it forward. Most application essays run 500 to 650 words. Ask a trusted adult to read your draft, cut repetition, and read it aloud.\n\nProverbs 27:2, Let another man praise thee, and not thine own mouth. Tell the truth plainly and humbly. Your task is to name three features, write an opening scene, and explain the lesson. Take the four question check. Your story matters. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.2 The Personal Narrative and the College Application Essay$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 23, $j$6.3 Professional Writing: Email, Resume and Cover Letter$j$, $j${"readings": [{"title": "Colossians 3 (King James Version)", "url": "/portal/bible/Colossians/3"}], "body": "Professional writing is clear, brief, polite and correct. It is how you will ask for a job, apply to a program, or communicate with a supervisor.\n\nA professional email has a specific subject line, a greeting by name, a short purpose statement in the first line, a few brief paragraphs or bullet points, a courteous close and your name and contact information. Avoid slang, all capital letters and emoji. Proofread every time.\n\nA resume is a one page summary of your qualifications. Typical sections are contact information, an objective or summary, education, experience (including volunteer and church service), skills, and honors. Begin each bullet with a strong action verb, such as organized, led, taught, repaired or coordinated, and include numbers where you can. For example: Coordinated weekly food pantry for 60 families.\n\nA cover letter introduces you to a specific employer. Paragraph one names the position and states your interest. Paragraph two gives two or three examples of your qualifications that match the job. Paragraph three thanks the reader and asks for an interview. Address it to a named person when possible and keep it to one page.\n\nWork done well is a form of worship. Colossians 3:23 says, And whatsoever ye do, do it heartily, as to the Lord, and not unto men.\n\nYour task: (1) Write a professional email subject line and a three sentence email asking a teacher or mentor for a recommendation letter. (2) Write three resume bullets that begin with action verbs. (3) Explain the purpose of each paragraph in a cover letter.\n\nFlorida standards: ELA.12.C.1.4, ELA.12.C.3.1, ELA.K12.EE.6.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.12.C.1.4, ELA.12.C.3.1, ELA.K12.EE.6.1", "script": "Welcome back. Listen, professional writing is clear, brief, polite and correct. It is how you will ask for a job, apply to a program or communicate with a supervisor.\n\nStart with email. A professional email has a specific subject line, a greeting by name, a purpose statement in the first line, a few brief paragraphs, a courteous close, and your name and contact information. No slang, no all capital letters, no emoji. And always proofread.\n\nNow watch this. A resume is a one page summary of your qualifications. It has contact information, a summary, education, experience including volunteer and church service, skills and honors. Start each bullet with a strong action verb, like organized, led, taught or coordinated, and include numbers when you can. For example, coordinated a weekly food pantry for sixty families.\n\nA cover letter introduces you to a specific employer. Paragraph one names the position and states your interest. Paragraph two gives two or three examples that match the job. Paragraph three thanks the reader and asks for an interview. Address it to a named person when possible and keep it to one page.\n\nColossians 3:23, whatsoever ye do, do it heartily, as to the Lord. Your task is to write a professional email, three resume bullets, and explain each paragraph of a cover letter. Take the four question check. Do all things with excellence. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.3 Professional Writing: Email, Resume and Cover Letter$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 24, $j$6.4 Public Speaking and the Capstone Presentation$j$, $j${"readings": [{"title": "1 Peter 3 (King James Version)", "url": "/portal/bible/1Peter/3"}], "body": "Speaking well is a skill for school, work and ministry. A strong presentation has a clear structure, confident delivery and a purpose that serves the audience.\n\nPlan with three questions: Who is my audience? What do I want them to know or do? How will I say it so they will remember? Then organize in three parts. The opening gets attention with a story, a question or a striking fact and states your main point. The body offers two or three main ideas, each with evidence and an example. The close restates your main point and gives a memorable final thought or call to action.\n\nFor delivery, stand with good posture, make eye contact, speak a little slower than normal, use pauses, and vary your voice. Avoid reading from your slides. If you use slides, keep them simple, with large text, few words and a helpful image. Practice aloud at least three times, and time yourself. Handle nerves by breathing slowly and focusing on serving your listeners, not on yourself.\n\nListen as well as speak. Be ready to answer questions politely. The apostle Peter wrote in 1 Peter 3:15, Be ready always to give an answer to every man that asketh you a reason of the hope that is in you with meekness and fear.\n\nYour capstone for this course is a final literary analysis essay and a short presentation of its main ideas.\n\nYour task: (1) Write a three part outline for a three minute talk on a work from this course. (2) Write an opening line that gets attention. (3) List three delivery tips you will practice.\n\nFlorida standards: ELA.12.C.2.1, ELA.12.C.5.1, ELA.12.C.5.2.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.12.C.2.1, ELA.12.C.5.1, ELA.12.C.5.2", "script": "Now let's talk about speaking. Listen, speaking well is a skill for school, for work and for ministry, and you have a voice worth hearing.\n\nPlan with three questions. Who is my audience? What do I want them to know or do? How will I say it so they will remember? Then organize in three parts. The opening gets attention with a story, a question or a striking fact, and states your main point. The body offers two or three main ideas, each with evidence and an example. The close restates your main point and leaves a memorable final thought.\n\nNow watch this. For delivery, stand with good posture, make eye contact, speak a little slower than normal, use pauses, and vary your voice. Do not read from your slides. Keep slides simple, with large text and few words. Practice aloud at least three times and time yourself. When nerves come, breathe slowly and focus on serving your listeners instead of yourself.\n\nAnd listen as well as speak. Be ready to answer questions politely. First Peter 3:15, be ready always to give an answer to every man that asketh you a reason of the hope that is in you with meekness and fear.\n\nYour capstone for this course is a final literary analysis essay and a short presentation of its main ideas. Your task is to write a three part outline, an opening line, and three delivery tips. Take the four question check. Speak with grace and truth. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.4 Public Speaking and the Capstone Presentation$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 6, $j$Assessment 6: Writing and Speaking for College, Career and Life$j$, $j${"prompt": "Complete a portfolio of writing and speaking pieces. Use complete sentences and label each part. Proverbs 22:29 says, Seest thou a man diligent in his business? he shall stand before kings; he shall not stand before mean men.\n\nPart 1: Write a research question and a thesis, and list three sources with a note on how you judge each by authority, accuracy, currency and purpose.\nPart 2: Write the first two paragraphs of a personal narrative or college application essay, beginning with a specific scene.\nPart 3: Write a professional email of about 100 words asking for a letter of recommendation or an interview.\nPart 4: Write a one page resume with at least five bullets that begin with action verbs, using your real or imagined service, school and church experience.\nPart 5: Write a three part outline for a three minute talk and an opening line.", "rubric": "100 points. Part 1: 20 points. Part 2: 25 points. Part 3: 15 points. Part 4: 20 points. Part 5: 15 points. Conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 6: Writing and Speaking for College, Career and Life$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 6, $j$Discussion 6: Your Voice and Your Calling$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes what you hope to do after high school, whether college, trade, military or ministry, (2) tells which writing or speaking skill from this unit you most need to improve and your plan to practice it, (3) explains why honesty matters in writing, research and speaking, and (4) connects your answer to Ephesians 4:15, which says, But speaking the truth in love, may grow up into him in all things, which is the head, even Christ. Then write a respectful reply of at least 40 words to another student's post, or answer this question: What makes a speaker or writer trustworthy? Keep your tone kind."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 6: Your Voice and Your Calling$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 26, $j$Check 6.1: Research and the Synthesis Essay$j$, $j${"questions": [{"q": "A synthesis essay:", "options": ["Lists quotations only", "Brings together ideas from several sources into your own supported point", "Summarizes one source", "Copies an article"]}, {"q": "Plagiarism is:", "options": ["Paraphrasing with credit", "Using a Works Cited list", "Quoting with credit", "Presenting someone else's words or ideas as your own"]}, {"q": "A primary source is:", "options": ["A textbook summary", "An original material such as a letter or speech", "A rumor", "A review"]}, {"q": "Judging a source by authority means asking:", "options": ["Who wrote it and what is their expertise", "What color is the cover", "Who owns the printer", "How long it is"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.1: Research and the Synthesis Essay$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,3,1,0}'::int[], array[$j$Synthesis creates a new point from several sources.$j$,$j$It is dishonest.$j$,$j$Secondary sources interpret primary sources.$j$,$j$Authority is about the author's qualifications.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.1: Research and the Synthesis Essay$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 27, $j$Check 6.2: The Personal Narrative and the College Application Essay$j$, $j${"questions": [{"q": "A strong personal narrative begins with:", "options": ["A general statement about the world", "A dictionary definition", "A specific scene", "A list of grades"]}, {"q": "Show, do not tell means:", "options": ["Skip details", "Avoid dialogue", "Use details and actions that prove a quality", "Only use adjectives"]}, {"q": "A typical application essay length is about:", "options": ["5,000 words", "10 words", "50 words", "500 to 650 words"]}, {"q": "Proverbs 27:2 teaches:", "options": ["Avoid all writing", "Let others praise you rather than your own mouth", "Hide your story", "Praise yourself often"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.2: The Personal Narrative and the College Application Essay$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,3,1}'::int[], array[$j$A small scene draws the reader in.$j$,$j$Details prove what you want to say.$j$,$j$Many applications set this range.$j$,$j$Share your accomplishments with humility.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.2: The Personal Narrative and the College Application Essay$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 28, $j$Check 6.3: Professional Writing: Email, Resume and Cover Letter$j$, $j${"questions": [{"q": "A professional email should have:", "options": ["A specific subject line", "Slang", "Emoji", "All capital letters"]}, {"q": "A resume bullet should begin with:", "options": ["A question", "The word I", "A joke", "A strong action verb"]}, {"q": "A cover letter is addressed to:", "options": ["A random person", "A specific employer, ideally by name", "A friend", "No one"]}, {"q": "Colossians 3:23 teaches us to work:", "options": ["Heartily, as to the Lord", "Only for pay", "Without effort", "Only when watched"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.3: Professional Writing: Email, Resume and Cover Letter$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,3,1,0}'::int[], array[$j$Clarity and respect are the standards.$j$,$j$Use verbs like led, organized or coordinated.$j$,$j$Personalize it to the position.$j$,$j$Excellent work honors God.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.3: Professional Writing: Email, Resume and Cover Letter$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 29, $j$Check 6.4: Public Speaking and the Capstone Presentation$j$, $j${"questions": [{"q": "A strong opening for a talk:", "options": ["Gets attention and states your main point", "Apologizes for being nervous", "Reads the slides", "Lists every source"]}, {"q": "The body of a speech should have:", "options": ["Twenty ideas", "Two or three main ideas with evidence", "No evidence", "Only jokes"]}, {"q": "A good delivery habit is to:", "options": ["Speak as fast as possible", "Avoid looking at anyone", "Read every word from slides", "Make eye contact and pause"]}, {"q": "1 Peter 3:15 advises us to answer with:", "options": ["Meekness and fear", "Silence", "Boasting", "Anger"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.4: Public Speaking and the Capstone Presentation$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,3,0}'::int[], array[$j$Hook the audience and state the point.$j$,$j$Keep ideas few and supported.$j$,$j$Eye contact and pauses help listeners follow.$j$,$j$Speak with humility and reverence.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.4: Public Speaking and the Capstone Presentation$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 30, $j$Unit Quiz 6: Writing and Speaking for College, Career and Life$j$, $j${"questions": [{"q": "Synthesis means:", "options": ["Guessing", "Listing quotes", "Copying one source", "Combining ideas from several sources"]}, {"q": "Plagiarism is:", "options": ["Revising", "Writing a draft", "Taking credit for another's words or ideas", "Giving credit"]}, {"q": "A resume bullet begins with:", "options": ["A question", "The word maybe", "A joke", "A strong action verb"]}, {"q": "A cover letter is meant to:", "options": ["Introduce you to a specific employer", "Ask for money", "List every class", "Replace a resume"]}, {"q": "A personal narrative should begin with:", "options": ["A specific scene", "A list of facts", "A summary of the ending", "A dictionary definition"]}, {"q": "A good speech has:", "options": ["Only a close", "An opening, a body and a close", "Only slides", "No structure"]}, {"q": "MLA is:", "options": ["A poem form", "A grammar error", "A citation style", "A Latin phrase"]}, {"q": "1 Peter 3:15 teaches:", "options": ["Win every argument", "Never speak", "Speak loudly", "Be ready to give an answer with meekness and fear"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 6: Writing and Speaking for College, Career and Life$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,2,3,0,0,1,2,3}'::int[], array[$j$Synthesis forms a new, supported point.$j$,$j$It is dishonest.$j$,$j$Action verbs show what you did.$j$,$j$It matches your qualifications to the job.$j$,$j$A scene hooks the reader.$j$,$j$Three part structure helps listeners.$j$,$j$MLA gives a consistent format for credit.$j$,$j$Humility and readiness go together.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 6: Writing and Speaking for College, Career and Life$j$ on conflict (item_id) do nothing;
